-- ALR-COST-ANOMALY (credit_anomaly): severity high, route tenant.alert_routes.finops, runbook RB-COST-ANOMALY, suppression 24h, owner FINOPS_LEAD
CREATE OR REPLACE ALERT OBS.OPS.ALR_COST_ANOMALY
  WAREHOUSE = OBS_WH
  SCHEDULE = 'USING CRON 15 6 * * * UTC'
  IF (EXISTS (
WITH s AS (SELECT ACCOUNT_NAME, DIMENSION AS DIM, PERIOD, SUM(VALUE) AS V FROM OBS.KPI.KPI_COST_001
           WHERE PERIOD >= DATEADD(DAY, -29, CURRENT_DATE()) GROUP BY 1, 2, 3),
     b AS (SELECT t.ACCOUNT_NAME, t.DIM, t.V, AVG(h.V) AS M, STDDEV_POP(h.V) AS SD, COUNT(h.V) AS N
           FROM s t JOIN s h ON h.ACCOUNT_NAME = t.ACCOUNT_NAME AND h.DIM = t.DIM AND h.PERIOD < t.PERIOD
            AND (DAYOFWEEKISO(h.PERIOD) IN (6, 7)) = (DAYOFWEEKISO(t.PERIOD) IN (6, 7))
           WHERE t.PERIOD = DATEADD(DAY, -1, CURRENT_DATE()) GROUP BY 1, 2, 3)
SELECT * FROM b WHERE N >= 3
  AND V > M + GREATEST(3 * SD, 0.25 * ABS(M))
  AND V - M >= 5
  ))
  THEN CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(
    SNOWFLAKE.NOTIFICATION.TEXT_PLAIN('[HIGH] Credit anomaly against the forecast band — runbook RB-COST-ANOMALY, owner FINOPS_LEAD'),
    SNOWFLAKE.NOTIFICATION.INTEGRATION('OBS_ROUTE_FINOPS'));
ALTER ALERT OBS.OPS.ALR_COST_ANOMALY RESUME;

